import { generateClient } from 'aws-amplify/api';

const client = generateClient();

// GraphQL mutations and queries
const createPushupLog = /* GraphQL */ `
  mutation CreatePushupLog($input: CreatePushupLogInput!) {
    createPushupLog(input: $input) {
      id
      userId
      count
      timestamp
      createdAt
      updatedAt
    }
  }
`;

const listPushupLogs = /* GraphQL */ `
  query ListPushupLogs($userId: ID!) {
    listPushupLogs(filter: { userId: { eq: $userId } }) {
      items {
        id
        userId
        count
        timestamp
        createdAt
        updatedAt
      }
    }
  }
`;

const deletePushupLog = /* GraphQL */ `
  mutation DeletePushupLog($input: DeletePushupLogInput!) {
    deletePushupLog(input: $input) {
      id
    }
  }
`;

export const DataSyncService = {
  // Upload a single log to AWS
  async uploadLog(userId, log) {
    try {
      const result = await client.graphql({
        query: createPushupLog,
        variables: {
          input: {
            userId,
            count: log.count,
            timestamp: log.timestamp
          }
        }
      });
      return result.data.createPushupLog;
    } catch (error) {
      console.error('Error uploading log:', error);
      throw error;
    }
  },

  // Upload multiple logs (batch)
  async uploadLogs(userId, logs) {
    try {
      const promises = logs.map(log => this.uploadLog(userId, log));
      return await Promise.all(promises);
    } catch (error) {
      console.error('Error uploading logs:', error);
      throw error;
    }
  },

  // Fetch all logs from AWS
  async fetchLogs(userId) {
    try {
      const result = await client.graphql({
        query: listPushupLogs,
        variables: { userId }
      });
      return result.data.listPushupLogs.items.map(item => ({
        count: item.count,
        timestamp: item.timestamp,
        id: item.id // Include AWS ID for deletion if needed
      }));
    } catch (error) {
      console.error('Error fetching logs:', error);
      throw error;
    }
  },

  // Sync localStorage with AWS (merge strategy)
  async syncData(userId, localLogs) {
    try {
      // Fetch cloud logs
      const cloudLogs = await this.fetchLogs(userId);
      
      // Create a map of cloud logs by timestamp for quick lookup
      const cloudLogMap = new Map(
        cloudLogs.map(log => [log.timestamp, log])
      );
      
      // Find logs that exist locally but not in cloud
      const logsToUpload = localLogs.filter(
        log => !cloudLogMap.has(log.timestamp)
      );
      
      // Upload missing logs
      if (logsToUpload.length > 0) {
        await this.uploadLogs(userId, logsToUpload);
      }
      
      // Create merged list (prioritize cloud data)
      const mergedLogs = [...cloudLogs];
      localLogs.forEach(log => {
        if (!cloudLogMap.has(log.timestamp)) {
          mergedLogs.push(log);
        }
      });
      
      // Sort by timestamp (newest first)
      mergedLogs.sort((a, b) => 
        new Date(b.timestamp) - new Date(a.timestamp)
      );
      
      return mergedLogs;
    } catch (error) {
      console.error('Error syncing data:', error);
      // If sync fails, return local data
      return localLogs;
    }
  },

  // Delete a log from AWS
  async deleteLog(logId) {
    try {
      await client.graphql({
        query: deletePushupLog,
        variables: {
          input: { id: logId }
        }
      });
    } catch (error) {
      console.error('Error deleting log:', error);
      throw error;
    }
  },

  async uploadMakeupEvent(_userId, event) {
    return event;
  },

  async fetchMakeupEvents() {
    return [];
  },

  async syncMakeupEvents(_userId, localEvents) {
    return localEvents;
  },

  async deleteMakeupEvent() {
    return;
  }
};
